@import url("https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@400;500;600;700&display=swap");

:root {
  /* tema homepage (dark, da grafica di riferimento) */
  --navy-950: #0a1520;
  --navy-900: #0d1b28;
  --navy-800: #122334;
  --navy-700: #1a3040;
  --gold: #d9a544;
  --gold-soft: #e8c377;
  --off-white: #f4f1e8;
  --hair: rgba(244, 241, 232, 0.12);
  --muted: rgba(244, 241, 232, 0.62);

  /* tema pagine interne (chiaro, invariato) */
  --ink: #16211f;
  --paper: #edeae0;
  --paper-raised: #e4e0d2;
  --deep: #132b2e;
  --water: #3e7d82;
  --line: #c98a3e;
  --border: rgba(22, 33, 31, 0.14);
}

* {
  box-sizing: border-box;
}

html,
body {
  padding: 0;
  margin: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  font-family: "Inter", system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3,
.display {
  font-family: "Fraunces", Georgia, serif;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.05;
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

a:focus-visible,
button:focus-visible {
  outline: 2px solid var(--water);
  outline-offset: 3px;
}

.wrap {
  max-width: 1040px;
  margin: 0 auto;
  padding: 0 24px;
}

.prose-width {
  max-width: 640px;
}

/* header */
.site-header {
  border-bottom: 1px solid var(--border);
  background: var(--paper);
  position: sticky;
  top: 0;
  z-index: 10;
}

.site-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 0;
}

.brand {
  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: 1.15rem;
}

.brand span {
  color: var(--water);
}

nav.main-nav {
  display: flex;
  gap: 28px;
  font-size: 0.94rem;
}

nav.main-nav a {
  padding-bottom: 3px;
  border-bottom: 1px solid transparent;
}

nav.main-nav a:hover {
  border-bottom-color: var(--line);
}

/* hero */
.hero {
  padding: 88px 0 64px;
  border-bottom: 1px solid var(--border);
}

.hero .eyebrow {
  color: var(--water);
  font-size: 0.92rem;
  margin-bottom: 14px;
}

.hero h1 {
  font-size: clamp(2.4rem, 5vw, 3.6rem);
  max-width: 12ch;
}

.hero p {
  max-width: 46ch;
  font-size: 1.1rem;
  line-height: 1.55;
  margin-top: 22px;
  color: rgba(22, 33, 31, 0.82);
}

.hero-actions {
  display: flex;
  gap: 16px;
  margin-top: 34px;
  flex-wrap: wrap;
}

.btn {
  display: inline-block;
  padding: 12px 22px;
  border-radius: 3px;
  font-size: 0.95rem;
  border: 1px solid var(--deep);
}

.btn-primary {
  background: var(--deep);
  color: var(--paper);
}

.btn-primary:hover {
  background: #0d2124;
}

.btn-secondary {
  background: transparent;
  color: var(--deep);
}

.btn-secondary:hover {
  background: var(--paper-raised);
}

/* section heading */
.section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin: 72px 0 28px;
}

.section-head h2 {
