  border-bottom: 1px solid var(--water);
}

/* logbook list (articoli) */
.logbook {
  border-top: 1px solid var(--border);
}

.log-entry {
  display: grid;
  grid-template-columns: 96px 1fr auto;
  gap: 20px;
  padding: 22px 0;
  border-bottom: 1px solid var(--border);
  align-items: baseline;
}

.log-entry .date {
  font-size: 0.82rem;
  color: rgba(22, 33, 31, 0.55);
  font-variant-numeric: tabular-nums;
}

.log-entry .title {
  font-family: "Fraunces", serif;
  font-weight: 500;
  font-size: 1.18rem;
}

.log-entry .cat {
  font-size: 0.78rem;
  color: var(--water);
  white-space: nowrap;
  align-self: baseline;
}

.log-entry:hover .title {
  color: var(--water);
}

/* cards for pillars (lenze, specie, diari) */
.pillars {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
  margin-top: 28px;
}

.pillar {
  background: var(--paper);
  padding: 30px 26px;
}

.pillar h3 {
  font-size: 1.15rem;
  margin-bottom: 10px;
}

.pillar p {
  font-size: 0.94rem;
  color: rgba(22, 33, 31, 0.75);
  line-height: 1.5;
}

.pillar .go {
  display: inline-block;
  margin-top: 16px;
  font-size: 0.86rem;
  color: var(--line);
  border-bottom: 1px solid var(--line);
}

footer.site-footer {
  border-top: 1px solid var(--border);
  margin-top: 100px;
  padding: 40px 0 60px;
  font-size: 0.86rem;
  color: rgba(22, 33, 31, 0.65);
}

footer.site-footer .foot-grid {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 24px;
}

@media (max-width: 760px) {
  nav.main-nav {
    display: none;
  }
  .pillars {
    grid-template-columns: 1fr;
  }
  .log-entry {
    grid-template-columns: 1fr;
    gap: 6px;
  }
}

/* ============================================
   HOMEPAGE — tema scuro (da grafica di riferimento)
   ============================================ */

.hp {
  background: var(--navy-900);
  color: var(--off-white);
}

.hp-display {
  font-family: "Anton", "Inter", sans-serif;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  line-height: 0.98;
}

/* header scuro */
.hp-header {
  background: var(--navy-950);
  border-bottom: 1px solid var(--hair);
  position: sticky;
  top: 0;
  z-index: 20;
}
.hp-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
}
.hp-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}
.hp-logo .ea {
  font-family: "Anton", sans-serif;
  font-size: 1.6rem;
  color: var(--gold);
  border: 2px solid var(--gold);
  padding: 2px 8px;
  line-height: 1;
}
.hp-logo .name {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  line-height: 1.35;
  color: var(--off-white);
}
.hp-nav {
  display: flex;
  align-items: center;
  gap: 34px;
}
.hp-nav a {
  font-size: 0.82rem;
  letter-spacing: 0.12em;
  color: var(--off-white);
  padding-bottom: 8px;
  border-bottom: 2px solid transparent;
}
.hp-nav a.active,
.hp-nav a:hover {
  border-bottom-color: var(--gold);
  color: var(--gold-soft);
}
.hp-social {
  display: flex;
  gap: 14px;
  margin-left: 10px;
}
.hp-social span {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(244, 241, 232, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
}

/* hero */
.hp-hero {
  position: relative;
  padding: 90px 0 40px;
  overflow: hidden;
  background: radial-gradient(ellipse at 70% 30%, #1a3550 0%, var(--navy-900) 65%);
}
.hp-hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 20px;
  align-items: center;
  position: relative;
  z-index: 2;
}
.hp-hero h1 {
  font-size: clamp(2.6rem, 5.4vw, 4.1rem);
}
.hp-hero h1 .line-gold {
  color: var(--gold);
  display: block;
}
.hp-hero h1 .line-white {
  color: var(--off-white);
  display: block;
}
.hp-hero p {
  margin-top: 24px;
  color: var(--muted);
  font-size: 1rem;
  line-height: 1.6;
  max-width: 42ch;
}
.hp-btn-gold {
  display: inline-block;
  margin-top: 30px;
  padding: 14px 28px;
  border: 1.5px solid var(--gold);
  color: var(--gold-soft);
  font-size: 0.85rem;
  letter-spacing: 0.1em;
  border-radius: 2px;
}
.hp-btn-gold:hover {
  background: var(--gold);
  color: var(--navy-950);
}
.hp-btn-solid {
  display: inline-block;
  padding: 14px 28px;
  background: var(--gold);
  color: var(--navy-950);
  font-size: 0.85rem;
  letter-spacing: 0.1em;
  border-radius: 2px;
  font-weight: 600;
}
.hp-btn-solid:hover {
  background: var(--gold-soft);
}

.photo-slot {
  border: 1.5px dashed rgba(244, 241, 232, 0.35);
  border-radius: 4px;
  background: linear-gradient(160deg, #16283a, #0d1b28);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--muted);
  font-size: 0.8rem;
  line-height: 1.5;
  padding: 20px;
}
.hp-hero .photo-slot {
  aspect-ratio: 4 / 3.3;
  border-radius: 6px;
  background: linear-gradient(160deg, #16283a, #0d1b28);
}
.hp-hero .photo-slot img { object-fit: contain !important; }

/* diari tecnici section */
.hp-diari {
  padding: 80px 0 90px;
  background: var(--navy-900);
}
.hp-diari-grid {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 60px;
  align-items: center;
}
.hp-eyebrow {
  color: var(--gold);
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  margin-bottom: 14px;
}
.hp-diari h2 {
  font-size: 2.1rem;
}
.hp-diari h2 .gold {
  color: var(--gold);
}
.hp-diari p {
  margin-top: 20px;
  color: var(--muted);
  line-height: 1.65;
  max-width: 40ch;
}
.hp-link-gold {
  display: inline-block;
  margin-top: 22px;
  color: var(--gold);
  font-size: 0.82rem;
  letter-spacing: 0.1em;
  border-bottom: 1px solid var(--gold);
  padding-bottom: 2px;
}
.hp-books {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.hp-books .photo-slot {
  aspect-ratio: 3 / 4.4;
}

/* app section */
.hp-app {
  background: linear-gradient(180deg, #0f2233, #0c1c2a);
  padding: 80px 0;
  border-top: 1px solid var(--hair);
  border-bottom: 1px solid var(--hair);
}
.hp-app-grid {
  display: grid;
  grid-template-columns: 0.55fr 1.45fr;
  gap: 50px;
  align-items: center;
}
.hp-app .photo-slot {
  aspect-ratio: 9 / 18;
  border-radius: 26px;
  background: linear-gradient(180deg, #0f2233, #0c1c2a);
}
.hp-app .photo-slot img { object-fit: contain !important; }
.hp-app h2 {
  font-size: 1.9rem;
  line-height: 1.15;
}
.hp-app h2 .gold {
  color: var(--gold);
  display: block;
}
.hp-app > .hp-app-grid > div:last-child > p:first-of-type {
  color: var(--muted);
  margin: 16px 0 34px;
}
.hp-features {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 26px;
}
.hp-feature .icon-slot {
  width: 46px;
  height: 46px;
  border: 1.5px solid var(--gold);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gold);
  font-size: 1.1rem;
  margin-bottom: 14px;
}
.hp-feature .ft {
  font-size: 0.86rem;
  letter-spacing: 0.06em;
  color: var(--off-white);
  margin-bottom: 6px;
}
.hp-feature p {
  font-size: 0.82rem;
  color: var(--muted);
  line-height: 1.5;
}
.hp-store-badges {
  display: flex;
  gap: 14px;
  margin-top: 34px;
  align-items: center;
}
.hp-store-badge {
  border: 1px solid var(--hair);
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 0.72rem;
  color: var(--muted);
}
.hp-badge-circle {
  margin-left: auto;
  width: 92px;
  height: 92px;
  border-radius: 50%;
  border: 1px dashed var(--gold);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--gold-soft);
  font-size: 0.68rem;
  line-height: 1.3;
}

/* dal blog / registro */
.hp-blog {
  padding: 80px 0 60px;
  background: var(--navy-900);
}
.hp-blog-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 30px;
}
.hp-blog-head h2 {
  font-size: 1.7rem;
  margin-top: 8px;
}
.hp-log {
  border-top: 1px solid var(--hair);
}
.hp-log-row {
  display: grid;
  grid-template-columns: 118px 100px 1fr 24px;
  gap: 20px;
  align-items: center;
  padding: 16px 0;
  border-bottom: 1px solid var(--hair);
  font-size: 0.94rem;
}
.hp-log-row:hover .hp-log-title {
  color: var(--gold-soft);
}
.hp-tag {
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  padding: 4px 10px;
  border: 1px solid;
  border-radius: 3px;
  text-align: center;
  width: fit-content;
}
.hp-tag.mare { color: #7fb2e0; border-color: #7fb2e0; }
.hp-tag.feeder { color: #a9b975; border-color: #a9b975; }
.hp-tag.tecnica { color: var(--gold-soft); border-color: var(--gold-soft); }
.hp-tag.attrezzatura { color: #b7bcc2; border-color: #b7bcc2; }
.hp-tag.acquadolce { color: #7fc79a; border-color: #7fc79a; }

.hp-log-date {
  color: var(--muted);
  font-size: 0.82rem;
}
.hp-log-title {
  color: var(--off-white);
}
.hp-log-go {
  color: var(--muted);
  text-align: right;
}

/* newsletter */
.hp-news {
  padding: 0;
  background: var(--navy-950);
}
.hp-news-grid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  min-height: 300px;
}
.hp-news .photo-slot {
  border: none;
  border-radius: 0;
  aspect-ratio: auto;
  height: 100%;
}
.hp-news-copy {
  padding: 60px 50px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.hp-news-copy h2 {
  font-size: 1.8rem;
}
.hp-news-copy p {
  color: var(--muted);
  margin-top: 14px;
  max-width: 42ch;
}
.hp-news-form {
  display: flex;
  gap: 12px;
  margin-top: 26px;
  max-width: 440px;
}
.hp-news-form input {
  flex: 1;
  background: rgba(244, 241, 232, 0.06);
  border: 1px solid var(--hair);
  border-radius: 3px;
  padding: 13px 16px;
  color: var(--off-white);
  font-size: 0.9rem;
}
.hp-news-form input::placeholder {
  color: var(--muted);
}
.hp-news-fine {
  margin-top: 12px;
  font-size: 0.76rem;
  color: var(--muted);
}

/* collab */
.hp-collab {
  padding: 50px 0;
  background: var(--navy-950);
  text-align: center;
  border-top: 1px solid var(--hair);
}
.hp-collab .hp-eyebrow {
  justify-content: center;
  display: block;
  margin-bottom: 26px;
}
.hp-collab-logos {
  display: flex;
  justify-content: center;
  gap: 60px;
  align-items: center;
}
.hp-collab-logos .photo-slot {
  width: 180px;
  height: 60px;
  aspect-ratio: auto;
  font-size: 0.7rem;
}

/* footer scuro */
.hp-footer {
  background: var(--navy-950);
  padding: 60px 0 30px;
  border-top: 1px solid var(--hair);
}
.hp-footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr 1fr;
  gap: 30px;
}
.hp-footer h4 {
  font-size: 0.76rem;
  letter-spacing: 0.1em;
  color: var(--gold-soft);
  margin-bottom: 16px;
}
.hp-footer a,
.hp-footer li {
  display: block;
  color: var(--muted);
  font-size: 0.86rem;
  margin-bottom: 10px;
}
.hp-footer a:hover {
  color: var(--gold-soft);
}
.hp-footer-bottom {
  display: flex;
  justify-content: space-between;
  margin-top: 40px;
  padding-top: 24px;
  border-top: 1px solid var(--hair);
  font-size: 0.78rem;
  color: var(--muted);
}

@media (max-width: 860px) {
  .hp-nav { display: none; }
  .hp-hero-grid,
  .hp-diari-grid,
  .hp-app-grid,
  .hp-news-grid {
    grid-template-columns: 1fr;
  }
  .hp-features { grid-template-columns: repeat(2, 1fr); }
  .hp-footer-grid { grid-template-columns: repeat(2, 1fr); }
  .hp-log-row { grid-template-columns: 90px 1fr; row-gap: 4px; }
  .hp-log-go { display: none; }
}

/* ================= WOW EFFECTS ================= */
.hp-header { transition: background .35s ease, box-shadow .35s ease, padding .35s ease; }
.hp-header.scrolled { background: rgba(10,21,32,0.86); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); box-shadow: 0 10px 34px rgba(0,0,0,0.4); }
.hp-header.scrolled .hp-header-inner { padding: 13px 0; }

.hp-hero { isolation: isolate; }
.hp-hero-glow { position: absolute; inset: -25%; z-index: 0; pointer-events: none; filter: blur(14px);
  background: radial-gradient(circle at 74% 32%, rgba(217,165,68,0.4), transparent 40%),
              radial-gradient(circle at 18% 82%, rgba(127,178,224,0.16), transparent 45%);
  animation: heroGlowPulse 7s ease-in-out infinite alternate; }
@keyframes heroGlowPulse { from { opacity: .75; transform: scale(1); } to { opacity: 1; transform: scale(1.1); } }

.hp-stars { position: absolute; inset: 0; z-index: 0; pointer-events: none; overflow: hidden; }
.hp-star { position: absolute; width: 2px; height: 2px; border-radius: 50%; background: #f4f1e8; animation: starTwinkle 3.6s ease-in-out infinite; }
@keyframes starTwinkle { 0%, 100% { opacity: .15; transform: scale(.7); } 50% { opacity: .95; transform: scale(1.4); } }

.hp-hero-grid { position: relative; z-index: 1; }

.hp-hero h1 .line-gold {
  background: linear-gradient(90deg, var(--gold-soft), var(--gold), #fff6dc, var(--gold-soft));
  background-size: 300% 100%; -webkit-background-clip: text; background-clip: text; color: transparent;
  animation: goldShimmer 5.5s linear infinite;
}
@keyframes goldShimmer { 0% { background-position: 0% 50%; } 100% { background-position: 300% 50%; } }

.hp-hero-photo-parallax { will-change: transform; }
.hp-hero .photo-slot {
  box-shadow: 0 0 0 1px rgba(217,165,68,.4), 0 30px 80px -20px rgba(217,165,68,.4), 0 0 60px rgba(217,165,68,.15);
  transition: transform .5s ease, box-shadow .5s ease;
}
.hp-hero .photo-slot:hover { transform: scale(1.015); box-shadow: 0 0 0 1px rgba(217,165,68,.6), 0 40px 100px -15px rgba(217,165,68,.55), 0 0 90px rgba(217,165,68,.25); }

.hp-btn-gold { position: relative; overflow: hidden; animation: ctaPulse 2.8s ease-in-out infinite; transition: transform .3s ease, box-shadow .3s ease, background .3s, color .3s; }
@keyframes ctaPulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(217,165,68,.35); } 50% { box-shadow: 0 0 26px 4px rgba(217,165,68,.35); } }
.hp-btn-gold:hover { transform: translateY(-2px) scale(1.03); }
.hp-btn-gold::after { content: ""; position: absolute; top: 0; left: -60%; width: 40%; height: 100%; background: linear-gradient(120deg, transparent, rgba(255,255,255,.5), transparent); transform: skewX(-20deg); transition: left .6s ease; }
.hp-btn-gold:hover::after { left: 130%; }

[data-reveal] { opacity: 0; transform: translateY(34px); transition: opacity .8s cubic-bezier(.2,.7,.3,1), transform .8s cubic-bezier(.2,.7,.3,1); }
[data-reveal].is-visible { opacity: 1; transform: translateY(0); }
[data-reveal-delay="1"] { transition-delay: .12s; }
[data-reveal-delay="2"] { transition-delay: .24s; }
[data-reveal-delay="3"] { transition-delay: .36s; }

.hp-books .photo-slot, .hp-app .photo-slot { transition: transform .45s cubic-bezier(.2,.7,.3,1), box-shadow .45s ease; }
.hp-books .photo-slot:hover { transform: translateY(-10px) scale(1.03) rotate(-.6deg); box-shadow: 0 30px 60px -10px rgba(0,0,0,.6), 0 0 40px rgba(217,165,68,.25); }
.hp-app .photo-slot:hover { transform: translateY(-6px) scale(1.02); box-shadow: 0 25px 50px -10px rgba(0,0,0,.5), 0 0 30px rgba(217,165,68,.2); }

.hp-feature { transition: transform .35s ease; }
.hp-feature:hover { transform: translateY(-4px); }
.hp-feature .icon-slot { transition: box-shadow .35s ease, transform .35s ease, background .35s ease; }
.hp-feature:hover .icon-slot { box-shadow: 0 0 0 4px rgba(217,165,68,.15), 0 0 24px rgba(217,165,68,.4); transform: scale(1.08); background: rgba(217,165,68,.08); }

.hp-log-row { transition: background .3s ease, padding-left .3s ease; }
.hp-log-row:hover { background: rgba(217,165,68,.05); padding-left: 8px; }

.hp-collab-logos .photo-slot { transition: transform .35s ease, filter .35s ease; filter: grayscale(.15); }
.hp-collab-logos .photo-slot:hover { transform: scale(1.06); filter: grayscale(0) drop-shadow(0 0 18px rgba(217,165,68,.35)); }

.hp-eyebrow { position: relative; padding-bottom: 10px; }
.hp-eyebrow::after { content: ""; position: absolute; left: 0; bottom: 0; height: 2px; width: 0; background: linear-gradient(90deg, var(--gold), transparent); transition: width .9s ease .15s; }
[data-reveal].is-visible .hp-eyebrow::after, .hp-eyebrow.is-visible::after { width: 56px; }

@media (prefers-reduced-motion: reduce) {
  .hp-hero-glow, .hp-star, .hp-hero h1 .line-gold, .hp-btn-gold { animation: none !important; }
  [data-reveal] { opacity: 1; transform: none; transition: none; }
}
/* ================= /WOW EFFECTS ================= */

/* ================= ADMIN ================= */
.admin-shell { max-width: 760px; margin: 0 auto; padding: 60px 24px 100px; color: var(--off-white); background: var(--navy-900); min-height: 100vh; font-family: "Inter", system-ui, sans-serif; }
.admin-login { max-width: 340px; margin: 80px auto 0; display: flex; flex-direction: column; gap: 14px; text-align: center; }
.admin-login h1 { font-size: 1.6rem; margin: 0; }
.admin-login p { color: var(--muted); margin: 0 0 6px; font-size: 0.9rem; }
.admin-login input { background: rgba(244,241,232,0.06); border: 1px solid var(--hair); border-radius: 4px; padding: 12px 14px; color: var(--off-white); font-size: 0.95rem; }
.admin-error { color: #e08a8a; font-size: 0.85rem; }

.admin-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 28px; }
.admin-top h1 { font-size: 1.7rem; margin: 0; }

.admin-warning { background: rgba(217,165,68,0.12); border: 1px solid rgba(217,165,68,0.4); color: var(--gold-soft); padding: 14px 16px; border-radius: 4px; font-size: 0.86rem; margin-bottom: 24px; line-height: 1.5; }
.admin-warning code { background: rgba(0,0,0,0.25); padding: 1px 6px; border-radius: 3px; }
.admin-ok { background: rgba(127,199,154,0.12); border: 1px solid rgba(127,199,154,0.4); color: #9fd9b6; padding: 12px 16px; border-radius: 4px; font-size: 0.86rem; margin-bottom: 24px; }

.admin-card { background: var(--navy-950); border: 1px solid var(--hair); border-radius: 6px; padding: 26px; margin-bottom: 28px; }
.admin-card h2 { font-size: 1.1rem; margin: 0 0 18px; }

.admin-form { display: flex; flex-direction: column; gap: 16px; }
.admin-form label { display: flex; flex-direction: column; gap: 6px; font-size: 0.82rem; color: var(--muted); }
.admin-form input, .admin-form select, .admin-form textarea {
  background: rgba(244,241,232,0.06); border: 1px solid var(--hair); border-radius: 4px;
  padding: 10px 12px; color: var(--off-white); font-size: 0.92rem; font-family: inherit;
}
.admin-form textarea { resize: vertical; }
.admin-form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.admin-form button { align-self: flex-start; margin-top: 4px; }
.admin-form button:disabled { opacity: 0.5; cursor: not-allowed; }

.admin-list { display: flex; flex-direction: column; }
.admin-list-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-bottom: 1px solid var(--hair); }
.admin-list-row:last-child { border-bottom: none; }
.admin-list-meta { color: var(--muted); font-size: 0.8rem; margin-top: 4px; }
